1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	// The MHPCO insures only the items on its price list. Anything else is a
74	// rejected policy, not a zero-priced one.
75	const lookUpByType = (table: Record<string, number>, type: string): number => {
76	  const value = table[type];
77	
78	  if (value === undefined) {
79	    throw new Error(`unknown item type: ${type}`);
80	  }
81	
82	  return value;
83	};
84	
85	// Rejecting uninsurable items is a rule of its own, so it is stated once and
86	// up front rather than left to fall out of whichever pricing step happens to
87	// look a type up first. Without this, a block of three unknown items would
88	// price through `baseOfGroup` untouched and only fail later, by luck, in the
89	// per-item surcharge pass.
90	const rejectUninsurableItems = (items: readonly Item[]): void => {
91	  for (const item of items) {
92	    lookUpByType(BASE_PREMIUMS, item.type);
93	  }
94	};
95	
96	const BLOCK_SIZE = 3;
97	const BLOCK_BASE_PREMIUM = 60;
98	
99	const countByType = (items: readonly Item[]): Map<string, number> => {
100	  const counts = new Map<string, number>();
101	
102	  for (const item of items) {
103	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
104	  }
105	
106	  return counts;
107	};
108	
109	// Prices one type-group. A block of exactly three costs a flat rate instead of
110	// three individual premiums — deliberately including main items, not just the
111	// small components. Callers have already rejected uninsurable types, so the
112	// flat-rate branch skipping the price list is safe rather than a hole.
113	const basePremiumOfTypeGroup = (type: string, count: number): number =>
114	  count === BLOCK_SIZE
115	    ? BLOCK_BASE_PREMIUM
116	    : count * lookUpByType(BASE_PREMIUMS, type);
117	
118	const policyBaseOf = (items: readonly Item[]): number =>
119	  [...countByType(items)].reduce(
120	    (total, [type, count]) => total + basePremiumOfTypeGroup(type, count),
121	    0,
122	  );
123	
124	// A modifier rule: when `applies` holds for the subject, `percent` percent of
125	// the relevant base premium is added. A negative percent is a discount. Every
126	// rule whose predicate holds contributes; the deltas are summed, never
127	// compounded.
128	type ModifierRule<Subject> = {
129	  applies: (subject: Subject) => boolean;
130	  percent: number;
131	};
132	
133	const sumApplicablePercents = <Subject>(
134	  rules: ModifierRule<Subject>[],
135	  subject: Subject,
136	): number =>
137	  rules.reduce(
138	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
139	    0,
140	  );
141	
142	// Policy-wide modifiers: each is a percentage of the policy base premium.
143	//
144	// Their subject is the circumstances under which the quote is issued — not the
145	// customer alone, and not the issued policy either (that is `IssuedPolicy`,
146	// which a claim reads). Today those circumstances are just who is asking and
147	// how many quotes they have had; rules that depend on more read the field they
148	// need off the same subject.
149	type QuoteCircumstances = {
150	  customer: Customer;
151	  // Zero-based ordinal among the customer's quotes in this scenario.
152	  quoteOrdinal: number;
153	};
154	
155	const LOYALTY_YEARS_THRESHOLD = 2;
156	const LOYALTY_DISCOUNT_PERCENT = -20;
157	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
158	
159	const POLICY_MODIFIER_RULES: ModifierRule<QuoteCircumstances>[] = [
160	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
161	  {
162	    applies: ({ customer }) =>
163	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
164	    percent: LOYALTY_DISCOUNT_PERCENT,
165	  },
166	  {
167	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
168	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
169	  },
170	];
171	
172	const policyModifierDelta = (
173	  policyBase: number,
174	  circumstances: QuoteCircumstances,
175	): number =>
176	  percentOf(
177	    policyBase,
178	    sumApplicablePercents(POLICY_MODIFIER_RULES, circumstances),
179	  );
180	
181	// Item-specific modifiers: each is a percentage of the affected item's own
182	// base premium.
183	const CURSE_SURCHARGE_PERCENT = 50;
184	const HIGH_ENCHANTMENT_THRESHOLD = 5;
185	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
186	
187	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
188	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
189	  {
190	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
191	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
192	  },
193	];
194	
195	const itemModifierDelta = (item: Item): number =>
196	  percentOf(
197	    lookUpByType(BASE_PREMIUMS, item.type),
198	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
199	  );
200	
201	const quote = (
202	  items: readonly Item[],
203	  circumstances: QuoteCircumstances,
204	): number => {
205	  rejectUninsurableItems(items);
206	
207	  const policyBase = policyBaseOf(items);
208	  const modifiers =
209	    policyModifierDelta(policyBase, circumstances) +
210	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
211	
212	  // Rounding is in the MHPCO's favour: premiums round up.
213	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
214	};
215	
216	// Insurance values are what an item is insured FOR, distinct from the base
217	// premium charged to insure it.
218	const INSURANCE_VALUES: Record<string, number> = {
219	  sword: 1000,
220	  amulet: 600,
221	  staff: 800,
222	  potion: 400,
223	  rune: 250,
224	  moonstone: 250,
225	};
226	
227	const DEDUCTIBLE_PER_DAMAGE = 100;
228	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
229	
230	const insuranceSumOf = (items: readonly Item[]): number =>
231	  items.reduce(
232	    (sum, item) => sum + lookUpByType(INSURANCE_VALUES, item.type),
233	    0,
234	  );
235	
236	// A policy as a claim sees it: the items it covers, and how much of its cap
237	// is still available. Successive claims against the same policy draw the cap
238	// down, so `remainingCap` is state that outlives the claim step that reads it.
239	type IssuedPolicy = {
240	  items: readonly Item[];
241	  remainingCap: number;
242	};
243	
244	const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
245	  items,
246	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
247	});
248	
249	// A reimbursement clause: when `applies` holds for the damaged item, the
250	// damage is reimbursed at `percent` of its amount.
251	//
252	// Unlike the premium modifiers above, clauses do NOT sum. When several apply
253	// the most restrictive one wins — the lowest percentage. So a clause table
254	// needs no ordering to be correct, and adding a clause can only ever lower a
255	// payout, never raise it.
256	type ReimbursementClause = {
257	  applies: (item: Item) => boolean;
258	  percent: number;
259	};
260	
261	const FULL_REIMBURSEMENT_PERCENT = 100;
262	const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
263	const HALVED_REIMBURSEMENT_PERCENT = 50;
264	
265	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
266	  {
267	    applies: (item) =>
268	      (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT,
269	    percent: HALVED_REIMBURSEMENT_PERCENT,
270	  },
271	];
272	
273	// Full reimbursement is the default: with no clause applying, the damage is
274	// covered in full.
275	const reimbursementPercentFor = (item: Item): number =>
276	  REIMBURSEMENT_CLAUSES.reduce(
277	    (percent, clause) =>
278	      clause.applies(item) ? Math.min(percent, clause.percent) : percent,
279	    FULL_REIMBURSEMENT_PERCENT,
280	  );
281	
282	// The damaged item a damage entry refers to, or undefined if the policy does
283	// not cover that type. Matched by type alone, so with two swords insured both
284	// sword damages resolve to the first. That is harmless while every item of a
285	// type is interchangeable for reimbursement purposes; the case that forces a
286	// positional match is rejecting more damage entries of a type than the policy
287	// covers, which needs a count rather than a lookup.
288	const insuredItemFor = (
289	  policy: IssuedPolicy,
290	  damage: Damage,
291	): Item | undefined =>
292	  policy.items.find((item) => item.type === damage.itemType);
293	
294	// A damage entry that has passed validation, paired with the insured item it
295	// was resolved against. Producing this is what the validation pass is *for*:
296	// downstream code takes the item as given rather than re-looking it up and
297	// re-handling a "not covered" case that can no longer occur.
298	type AdmittedDamage = {
299	  damage: Damage;
300	  damagedItem: Item;
301	};
302	
303	const countDamagesByType = (
304	  damages: readonly Damage[],
305	): Map<string, number> => {
306	  const counts = new Map<string, number>();
307	
308	  for (const damage of damages) {
309	    counts.set(damage.itemType, (counts.get(damage.itemType) ?? 0) + 1);
310	  }
311	
312	  return counts;
313	};
314	
315	// Admits an incident's damages, or refuses the claim outright. Stated here,
316	// once and up front, for the same reason `rejectUninsurableItems` is: a
317	// rejection is a rule in its own right, not something that should fall out of
318	// whichever computation step happens to trip over it first.
319	//
320	// Running before any money is computed also keeps the settlement total — a
321	// function that can throw partway through an accumulation is doing control
322	// flow through the accumulator.
323	//
324	// This is the incident-level pass, so a rule that needs to see all the damages
325	// at once — counting entries per type against what the policy covers — has a
326	// home here, whereas it could never live inside a per-damage function.
327	const admitDamages = (
328	  policy: IssuedPolicy,
329	  incident: Incident,
330	): AdmittedDamage[] => {
331	  // A policy cannot lose more of a thing than it insures.
332	  const insuredCounts = countByType(policy.items);
333	
334	  for (const [itemType, damagedCount] of countDamagesByType(incident.damages)) {
335	    if (damagedCount > (insuredCounts.get(itemType) ?? 0)) {
336	      throw new Error(
337	        `more ${itemType} damages than the policy covers: ` +
338	          `${damagedCount} of ${insuredCounts.get(itemType) ?? 0}`,
339	      );
340	    }
341	  }
342	
343	  return incident.damages.map((damage) => {
344	    // Damage is a loss, never a credit.
345	    if (damage.amount < 0) {
346	      throw new Error(`negative damage amount: ${damage.amount}`);
347	    }
348	
349	    const damagedItem = insuredItemFor(policy, damage);
350	
351	    // A policy only answers for what it covers.
352	    if (damagedItem === undefined) {
353	      throw new Error(`item not covered by the policy: ${damage.itemType}`);
354	    }
355	
356	    return { damage, damagedItem };
357	  });
358	};
359	
360	// What a single admitted damage is reimbursable for: the reimbursement its
361	// clauses allow, less the deductible. The deductible is charged once per
362	// damaged item, not once per incident, so it belongs here rather than at the
363	// incident level. The policy's cap is NOT applied here — it limits the
364	// incident as a whole, so only `settleClaim` can apply it.
365	//
366	// The clauses grade the reimbursement by the *damaged item's* properties
367	// (enchantment, material), which is why the resolved item travels with the
368	// damage instead of the policy being passed in to look it up again.
369	const reimbursableForDamage = ({
370	  damage,
371	  damagedItem,
372	}: AdmittedDamage): number =>
373	  percentOf(damage.amount, reimbursementPercentFor(damagedItem)) -
374	  DEDUCTIBLE_PER_DAMAGE;
375	
376	// Settles one incident against a policy, returning the payout and the policy
377	// as it stands afterwards. The cap is drawn down here — that is what makes a
378	// second claim against the same policy see less headroom than the first.
379	const settleClaim = (
380	  policy: IssuedPolicy,
381	  incident: Incident,
382	): { payout: number; policy: IssuedPolicy } => {
383	  // Admit every damage before paying for any: a claim is refused as a whole,
384	  // so no part of it should be priced until all of it is known to be valid.
385	  const admitted = admitDamages(policy, incident);
386	
387	  const reimbursable = admitted.reduce(
388	    (total, admittedDamage) => total + reimbursableForDamage(admittedDamage),
389	    0,
390	  );
391	
392	  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
393	  // premium's round up.
394	  // The policy pays at most what is left of its cap.
395	  const payout = Math.min(Math.floor(reimbursable), policy.remainingCap);
396	
397	  return {
398	    payout,
399	    policy: { ...policy, remainingCap: policy.remainingCap - payout },
400	  };
401	};
402	
403	// What the scenario has established by the time a step runs. Threaded through
404	// the steps in order: each step reads it, and hands the next step the progress
405	// its own execution made.
406	type ScenarioProgress = {
407	  // How many quotes the customer has already been given. Only quote steps
408	  // advance this, so an op that is not a quote leaves it untouched.
409	  quotesSoFar: number;
410	  // Policies created by earlier quote steps, keyed by their step index — the
411	  // handle a later claim step names in its `policy` field.
412	  policies: Map<number, IssuedPolicy>;
413	};
414	
415	// The policy a claim step names. A claim against an index no quote step
416	// created currently settles against an empty policy: no items, so every damage
417	// is uncovered, and a zero cap. That is a placeholder standing in for a rule
418	// nobody has written yet, not a decision — the honest behaviour is almost
419	// certainly to reject the claim outright, the way an unknown item type is
420	// rejected. Named here so the choice is visible at the point it is made, and
421	// so the test that pins it down has one place to change.
422	const policyClaimedAgainst = (
423	  policies: ReadonlyMap<number, IssuedPolicy>,
424	  policyIndex: number,
425	): IssuedPolicy => policies.get(policyIndex) ?? issuePolicy([]);
426	
427	// Runs one step against the progress so far, returning its result alongside
428	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
429	// a new op is a new branch, and the loop below is unaffected.
430	const runStep = (
431	  step: Step,
432	  stepIndex: number,
433	  customer: Customer,
434	  progress: ScenarioProgress,
435	): { result: StepResult; progress: ScenarioProgress } => {
436	  if (step.op === "claim") {
437	    const settled = settleClaim(
438	      policyClaimedAgainst(progress.policies, step.policy),
439	      step.incident,
440	    );
441	
442	    return {
443	      result: {
444	        payout: settled.payout,
445	        remainingCap: settled.policy.remainingCap,
446	      },
447	      // The drawn-down policy replaces the one the claim was made against, so
448	      // the next claim against it starts from the reduced cap.
449	      progress: {
450	        ...progress,
451	        policies: new Map(progress.policies).set(step.policy, settled.policy),
452	      },
453	    };
454	  }
455	
456	  return {
457	    result: {
458	      premium: quote(step.items, {
459	        customer,
460	        quoteOrdinal: progress.quotesSoFar,
461	      }),
462	    },
463	    progress: {
464	      quotesSoFar: progress.quotesSoFar + 1,
465	      policies: new Map(progress.policies).set(
466	        stepIndex,
467	        issuePolicy(step.items),
468	      ),
469	    },
470	  };
471	};
472	
473	export const runScenario = (scenario: Scenario): ScenarioResult => {
474	  const results: StepResult[] = [];
475	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
476	
477	  for (const [stepIndex, step] of scenario.steps.entries()) {
478	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
479	
480	    results.push(stepRun.result);
481	    progress = stepRun.progress;
482	  }
483	
484	  return { results };
485	};
